parameters.jsCode:
// Aggregate all data into a report structure
const ga4Overview = $('GA4: Overview').item.json || {};
const ga4TopPages = $('GA4: Top Pages').item.json || {};
const posthogEvents = $('PostHog: Key Events').item.json || {};
const searchConsole = $('Search Console: Keywords').item.json || {};

// Parse GA4 overview (current vs previous week)
const parseGA4Row = (row) => {
  if (!row?.metricValues) return {};
  return {
    sessions: parseInt(row.metricValues[0]?.value || 0),
    users: parseInt(row.metricValues[1]?.value || 0),
    newUsers: parseInt(row.metricValues[2]?.value || 0),
    pageviews: parseInt(row.metricValues[3]?.value || 0),
    conversions: parseInt(row.metricValues[4]?.value || 0),
    avgSessionDuration: parseFloat(row.metricValues[5]?.value || 0)
  };
};

const currentWeek = parseGA4Row(ga4Overview.rows?.[0]);
const previousWeek = parseGA4Row(ga4Overview.rows?.[1]);

// Calculate week-over-week changes
const calculateChange = (current, previous) => {
  if (!previous || previous === 0) return 'N/A';
  const change = ((current - previous) / previous * 100).toFixed(1);
  return change > 0 ? `+${change}%` : `${change}%`;
};

// Parse top pages
const topPages = (ga4TopPages.rows || []).slice(0, 5).map(row => ({
  path: row.dimensionValues?.[0]?.value || '',
  views: parseInt(row.metricValues?.[0]?.value || 0),
  conversions: parseInt(row.metricValues?.[1]?.value || 0)
}));

// Parse search console keywords
const topKeywords = (searchConsole.rows || []).slice(0, 10).map(row => ({
  keyword: row.keys?.[0] || '',
  clicks: row.clicks || 0,
  impressions: row.impressions || 0,
  ctr: ((row.ctr || 0) * 100).toFixed(1) + '%',
  position: (row.position || 0).toFixed(1)
}));

return {
  json: {
    period: `${$now.minus({days: 7}).toFormat('MMM d')} - ${$now.minus({days: 1}).toFormat('MMM d, yyyy')}`,
    overview: {
      sessions: currentWeek.sessions,
      sessionsChange: calculateChange(currentWeek.sessions, previousWeek.sessions),
      users: currentWeek.users,
      usersChange: calculateChange(currentWeek.users, previousWeek.users),
      newUsers: currentWeek.newUsers,
      pageviews: currentWeek.pageviews,
      conversions: currentWeek.conversions,
      conversionsChange: calculateChange(currentWeek.conversions, previousWeek.conversions),
      avgSessionDuration: Math.round(currentWeek.avgSessionDuration) + 's'
    },
    topPages,
    topKeywords,
    hasData: currentWeek.sessions > 0
  }
};

